internal static class AuraSyncCoordinatorTests {
 static int count;static readonly DateTime Now=new DateTime(2026,10,13,0,0,0,DateTimeKind.Utc);
 static void Check(bool yes,string message){count++;if(!yes)throw new Exception(message);}
 static Dictionary<string,object> Obj(params object[] pairs){var result=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)result[(string)pairs[i]]=pairs[i+1];return result;}
 static void Reject(Action callback,string message){bool failed=false;try{callback();}catch(ArgumentException){failed=true;}catch(InvalidOperationException){failed=true;}Check(failed,message);}
 static Dictionary<string,object> Direct(){return Obj("id","native-aura-synthetic01","backend","native-hid","vendorId","0B05","productId","1AA6","controllerFamily","motherboard","zoneCount",2,"leds",8,"effects",new[]{"static","breathe","cycle","off"},"effectWriteValidated",false);}
 static Dictionary<string,object> Headset(){return Obj("deviceId","hid-synthetic-headset01","kind","headset","pid",7489,"model","Synthetic headset","transport","rf","online",true,"readbackConfirmed",true,"setCapabilities",new[]{"brightness","lightingEffect","lightingColor","lightingEnabled"},"snapshot",Obj("lightingEffectCode",2,"brightnessRaw",50,"color",new[]{1,2,3},"lightingEnabled",true,"auraEnabled",false));}
 static AuraSyncCommandReply Confirm(){return new AuraSyncCommandReply{Ok=true,Accepted=true,WriteAttempted=true,WriteConfirmed=true};}
 static Task<AuraSyncTarget> Fresh(AuraSyncTarget target){return Task.FromResult(target);}
 static Dictionary<string,object> MouseState(bool software=true){return Obj("kind","mouse","pid",7548,"deviceId","hid-synthetic-lighting","model","Synthetic mouse","online",true,"readbackConfirmed",true,"readCapabilities",new[]{"lighting","lightingSoftwareMode","windowsLightingEnabled"},"setCapabilities",software?new[]{"lightingSoftwareMode"}:new[]{"lightingSoftwareMode","staticLighting"},"snapshot",Obj("uniformStaticLightingProtocolAvailable",true,"uniformStaticLightingReady",!software,"lightingSoftwareMode",software,"windowsLightingEnabled",false,"lighting",Obj("currentMode",2,"area",0,"brightness",100,"speed",0,"direction",0,"random",false,"color",new[]{48,0,109})));}
 static int Main(){try{Run().GetAwaiter().GetResult();Console.WriteLine("Aura static coordination: "+count+" synthetic checks passed; worker requests 0, hardware writes 0.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.GetBaseException().Message);return 1;}}
 static async Task Run(){
  var direct=AuraSyncCoordinator.Direct(Direct(),"Synthetic motherboard",Now);Check(direct.CanStaticRgb&&direct.Online,"Native read-backed static capability");Check(!direct.PhysicalWriteValidated,"Source support is not physical-write validation");
  var unsupported=Direct();unsupported["vendorId"]="FFFF";Check(!AuraSyncCoordinator.Direct(unsupported,"board",Now).CanStaticRgb,"Unknown vendor rejected");
  unsupported=Direct();unsupported["productId"]="1ABC";Check(!AuraSyncCoordinator.Direct(unsupported,"board",Now).CanStaticRgb,"Unknown PID not inferred by family name");
  unsupported=Direct();unsupported["zoneCount"]=0;Check(!AuraSyncCoordinator.Direct(unsupported,"board",Now).CanStaticRgb,"No confirmed lighting zone rejected");
  unsupported=Direct();unsupported["effects"]=new[]{"cycle"};Check(!AuraSyncCoordinator.Direct(unsupported,"board",Now).CanStaticRgb,"Nonuniform hardware cycle is not static sync");
  var state=Headset();var headset=AuraSyncCoordinator.Gear(state,Now);Check(headset.CanStaticRgb,"Known headset full lighting getters permit plan");
  var snapshot=(Dictionary<string,object>)state["snapshot"];snapshot["lightingEffectCode"]=0;Check(!AuraSyncCoordinator.Gear(state,Now).CanStaticRgb,"Unmapped actual raw0 disables color sync");
  snapshot["lightingEffectCode"]=2;snapshot["auraEnabled"]=true;Check(!AuraSyncCoordinator.Gear(state,Now).CanStaticRgb,"Unproven hardware Aura ownership rejected");
  snapshot["auraEnabled"]=false;snapshot["color"]=new[]{1,2};Check(!AuraSyncCoordinator.Gear(state,Now).CanStaticRgb,"Incomplete color readback rejected");
  snapshot["color"]=new[]{1,2,3};state["setCapabilities"]=new[]{"brightness","lightingEffect"};Check(!AuraSyncCoordinator.Gear(state,Now).CanStaticRgb,"Missing color setter rejected");
  state=Headset();state["online"]=false;Check(!AuraSyncCoordinator.Gear(state,Now).CanStaticRgb,"Offline device unavailable");
  state=Headset();state["pid"]=9999;Check(!AuraSyncCoordinator.Gear(state,Now).CanStaticRgb,"Unsupported headset PID unavailable");
  foreach(string kind in new[]{"keyboard","mouse"}){state=Headset();state["kind"]=kind;Check(!AuraSyncCoordinator.Gear(state,Now).CanStaticRgb,"Lighting not inferred for other kind");}
  var fan=AuraSyncCoordinator.Fan(Obj("readbackConfirmed",true,"supportsLighting",true,"effectCapabilities",new[]{Obj("effect","static")},"fanCounts",null),Now);Check(fan.Online&&!fan.CanStaticRgb&&fan.UnavailableReason.Contains("数量"),"EURUX draft fan count never forwarded");
  var identified=AuraSyncCoordinator.Identified(Obj("deviceId",new string('a',64),"name","Synthetic future device","present",true),Now);Check(identified.Online&&!identified.CanStaticRgb,"Windows discovery is not control support");
  Check(AuraSyncCoordinator.OutputColor("static","#804020",50)=="#402010","Uniform software brightness scaling");
  Check(AuraSyncCoordinator.OutputColor("off","#ABCDEF",100)=="#000000","Off means common black static RGB");
  Check(AuraSyncCoordinator.OutputColor("static","#ABCDEF",0)=="#000000","Zero brightness uniform black");
  foreach(string effect in new[]{"breathe","cycle","rainbow","music"})Reject(()=>AuraSyncCoordinator.OutputColor(effect,"#123456",100),"Autonomous effects not called phase sync");
  Reject(()=>AuraSyncCoordinator.OutputColor("static","#123",100),"Malformed RGB rejected");Reject(()=>AuraSyncCoordinator.OutputColor("static","#123456",101),"Brightness range enforced");
  var plan=AuraSyncCoordinator.BuildStaticCommands(direct,"#102030");Check(plan.Length==1&&(string)plan[0].Request["effect"]=="static"&&(int)plan[0].Request["brightness"]==100,"Native static plan single request");
  Check(((string[])plan[0].Request["devices"]).SequenceEqual(new[]{direct.DeviceId}),"Native exact ID selection");
  headset=AuraSyncCoordinator.Gear(Headset(),Now);plan=AuraSyncCoordinator.BuildStaticCommands(headset,"#102030");Check(plan.Select(step=>step.Setting).SequenceEqual(new[]{"brightness","lightingEffect","lightingColor"}),"Headset explicit safe sequence");
  Check(plan.All(step=>(bool)step.Request["experimental"]),"Gear requires experiment consent flag");
  Check(((int[])plan.Last().Request["value"]).SequenceEqual(new[]{16,32,48}),"Same final RGB bytes");
  state=Headset();((Dictionary<string,object>)state["snapshot"])["lightingEnabled"]=false;Check(AuraSyncCoordinator.BuildStaticCommands(AuraSyncCoordinator.Gear(state,Now),"#102030")[0].Setting=="lightingEnabled","Disabled lights require known reversible enable setter");
  Reject(()=>AuraSyncCoordinator.BuildStaticCommands(fan,"#102030"),"EURUX never builds topology-changing request");
  Reject(()=>AuraSyncCoordinator.BuildStaticCommands(identified,"#102030"),"Unknown device builds no command");
  var coordinator=new AuraSyncCoordinator();var events=new List<string>();int gates=0,sends=0;
  var result=await coordinator.ApplyAsync(new[]{direct,headset},new[]{direct.Id,headset.Id},"static","#102030",100,target=>{events.Add("read:"+target.Id);return Fresh(target);},command=>{events.Add("write:"+command.TargetId);sends++;return Task.FromResult(command.Backend=="direct"?new AuraSyncCommandReply{Ok=true,Accepted=true,WriteAttempted=true,WriteConfirmed=false}:Confirm());},()=>gates++);
  Check(events.Take(2).All(value=>value.StartsWith("read:")),"Every target preflight precedes first output");Check(sends==4&&gates==4,"Permission demanded per actual command");
  Check(result.Devices.Length==2&&result.Devices[0].State=="submittedUnconfirmed"&&result.Devices[1].ReadbackConfirmed,"Per-device readback evidence distinguished");
  Check(result.AllSubmitted&&!result.AllReadbackConfirmed,"ACK alone not globally confirmed sync");Check(!coordinator.Running,"Coordinator released after completion");
  sends=0;var blocked=await new AuraSyncCoordinator().ApplyAsync(new[]{direct},new[]{direct.Id},"static","#102030",100,Fresh,command=>{sends++;return Task.FromResult(Confirm());},()=>{throw new InvalidOperationException("policy disabled");});
  Check(sends==0&&blocked.Devices[0].State=="failed","Disabled session policy sends nothing");
  sends=0;gates=0;var revoked=await new AuraSyncCoordinator().ApplyAsync(new[]{headset},new[]{headset.Id},"static","#102030",100,Fresh,command=>{sends++;return Task.FromResult(Confirm());},()=>{if(++gates==2)throw new InvalidOperationException("revoked");});
  Check(sends==1&&revoked.Devices[0].CommandsCompleted==1&&!revoked.Devices[0].ReadbackConfirmed,"Mid-sequence revocation stops remaining output");
  sends=0;var uncertain=await new AuraSyncCoordinator().ApplyAsync(new[]{headset},new[]{headset.Id},"static","#102030",100,Fresh,command=>{sends++;return Task.FromResult(new AuraSyncCommandReply{Ok=true,Accepted=true,WriteAttempted=true,WriteConfirmed=false});},()=>{});
  Check(sends==1&&uncertain.Devices[0].State=="unconfirmed","Unconfirmed Gear command stops that target without retries");
  sends=0;var disconnected=await new AuraSyncCoordinator().ApplyAsync(new[]{direct},new[]{direct.Id},"static","#102030",100,target=>Task.FromResult(AuraSyncCoordinator.Missing("motherboard","board","offline",Now)),command=>{sends++;return Task.FromResult(Confirm());},()=>{});
  Check(sends==0&&disconnected.Devices[0].State=="preflightFailed","Identity/connection change blocks write");
  sends=0;var timeout=await new AuraSyncCoordinator().ApplyAsync(new[]{direct,headset},new[]{direct.Id,headset.Id},"static","#102030",100,Fresh,command=>{sends++;if(command.Backend=="direct")throw new TimeoutException("synthetic timeout");return Task.FromResult(Confirm());},()=>{});
  Check(sends==4&&timeout.Devices[0].State=="failed"&&timeout.Devices[1].ReadbackConfirmed,"One target timeout no resend, other target result retained");
  var cancelled=new AuraSyncCoordinator();sends=0;var stopped=await cancelled.ApplyAsync(new[]{headset},new[]{headset.Id},"static","#102030",100,Fresh,command=>{sends++;cancelled.RequestStop();return Task.FromResult(Confirm());},()=>{});
  Check(sends==1&&stopped.Cancelled&&stopped.Devices[0].State=="cancelled","Stop prevents future commands without restoring hardware");
  int reads=0;Reject(()=>new AuraSyncCoordinator().ApplyAsync(new[]{direct},new string[0],"static","#102030",100,target=>{reads++;return Fresh(target);},command=>Task.FromResult(Confirm()),()=>{}).GetAwaiter().GetResult(),"Empty selection rejected");Check(reads==0,"Invalid selection performs no read/write callbacks");
  var noop=await new AuraSyncCoordinator().ApplyAsync(new[]{headset},new[]{headset.Id},"static","#102030",100,Fresh,command=>Task.FromResult(new AuraSyncCommandReply{Ok=true,Accepted=false,WriteAttempted=false,WriteConfirmed=true}),()=>{});
  Check(noop.AllReadbackConfirmed&&!noop.Devices[0].WriteAttempted,"Already-set confirmation is not a physical write");
  var streaming=AuraSyncCoordinator.Gear(MouseState(),Now);Check(streaming.CanReleaseSoftwareLighting&&!streaming.CanStaticRgb,"Streaming mouse requires distinct manual ownership action");Reject(()=>AuraSyncCoordinator.BuildStaticCommands(streaming,"#102030"),"Apply cannot silently take ownership");
  var released=AuraSyncCoordinator.Gear(MouseState(false),Now);Check(released.CanStaticRgb&&!released.CanReleaseSoftwareLighting,"Released getter enables static selection");plan=AuraSyncCoordinator.BuildStaticCommands(released,"#102030");Check(plan.Length==1&&plan[0].Setting=="staticLighting","One explicit static RGB packet after ownership confirmation");
  state=MouseState(false);((Dictionary<string,object>)((Dictionary<string,object>)state["snapshot"])["lighting"])["currentMode"]=255;Check(!AuraSyncCoordinator.Gear(state,Now).CanStaticRgb,"Unknown effect cannot gain source flag support");
  state=MouseState();((Dictionary<string,object>)state["snapshot"])["windowsLightingEnabled"]=true;Check(!AuraSyncCoordinator.Gear(state,Now).CanReleaseSoftwareLighting,"WDL is never implicitly disabled");
  int ownershipReads=0;gates=0;sends=0;var ownership=await new AuraSyncCoordinator().TakeSoftwareLightingAsync(streaming,target=>Task.FromResult(++ownershipReads==1?streaming:released),command=>{sends++;Check(command.Setting=="lightingSoftwareMode"&&command.Request["value"] is bool&&!(bool)command.Request["value"],"Only software flag release sent");return Task.FromResult(Confirm());},()=>gates++);
  Check(ownership.OwnershipConfirmed&&sends==1&&gates==1&&ownership.Steps.SequenceEqual(new[]{"baselineRead","releaseRequested","releaseReadback"}),"Ownership separate getter/permission/output/readback transaction");
  ownershipReads=0;sends=0;gates=0;ownership=await new AuraSyncCoordinator().TakeSoftwareLightingAsync(streaming,target=>{ownershipReads++;return Task.FromResult(ownershipReads==1||ownershipReads==4?streaming:released);},command=>{sends++;return Task.FromResult(sends==1?new AuraSyncCommandReply{Ok=true,Accepted=true,WriteAttempted=true,WriteConfirmed=false}:Confirm());},()=>gates++);
  Check(!ownership.OwnershipConfirmed&&ownership.RestorationConfirmed&&sends==2&&gates==2,"Unconfirmed release restores exact original flag once");Check(ownership.Steps.Count(step=>step=="restoreOriginalSoftwareFlag")==1,"No rollback retries");
  ownershipReads=0;sends=0;ownership=await new AuraSyncCoordinator().TakeSoftwareLightingAsync(streaming,target=>{if(++ownershipReads>1)throw new TimeoutException("offline");return Fresh(streaming);},command=>{sends++;return Task.FromResult(Confirm());},()=>{});
  Check(!ownership.OwnershipConfirmed&&!ownership.RestorationConfirmed&&sends==1&&ownership.RestorationState=="unconfirmed","Offline restoration is not blindly written or reported successful");
  sends=0;ownership=await new AuraSyncCoordinator().TakeSoftwareLightingAsync(streaming,Fresh,command=>{sends++;return Task.FromResult(Confirm());},()=>{throw new InvalidOperationException("disabled");});Check(sends==0&&!ownership.WriteAttempted&&ownership.RestorationState=="notNeeded","Disabled policy prevents ownership and rollback output");
  ownershipReads=0;sends=0;gates=0;ownership=await new AuraSyncCoordinator().TakeSoftwareLightingAsync(streaming,target=>Task.FromResult(++ownershipReads==1?streaming:released),command=>{sends++;return Task.FromResult(new AuraSyncCommandReply{Ok=true,Accepted=true,WriteAttempted=true,WriteConfirmed=false});},()=>{if(++gates>1)throw new InvalidOperationException("revoked");});Check(sends==1&&!ownership.RestorationConfirmed&&ownership.RestorationState=="unconfirmed","Permission revocation blocks original-flag restore rather than bypass policy");
  var stopOwnership=new AuraSyncCoordinator();sends=0;ownership=await stopOwnership.TakeSoftwareLightingAsync(streaming,Fresh,command=>{sends++;stopOwnership.RequestStop();return Task.FromResult(Confirm());},()=>{});Check(sends==1&&ownership.State=="stopped"&&ownership.RestorationState=="notAttemptedStopped","Stop releases process without restoration writes");
  sends=0;ownership=await new AuraSyncCoordinator().TakeSoftwareLightingAsync(streaming,target=>Fresh(released),command=>{sends++;return Task.FromResult(Confirm());},()=>{});Check(sends==0&&ownership.State=="alreadyAvailable"&&ownership.OwnershipConfirmed,"Concurrent original flag change read back as no-output");
  ownershipReads=0;sends=0;ownership=await new AuraSyncCoordinator().TakeSoftwareLightingAsync(streaming,Fresh,command=>{sends++;throw new TimeoutException("failed");},()=>{});Check(sends==1&&ownership.RestorationConfirmed&&ownership.RestorationState=="originalFlagReadback","Original flag still present needs no restore command");
  state=MouseState();state["kind"]="keyboard";state["pid"]=7588;var keyboardSnapshot=(Dictionary<string,object>)state["snapshot"];keyboardSnapshot.Remove("lighting");keyboardSnapshot["uniformStaticLightingProtocolAvailable"]=false;var keyboardAttempt=AuraSyncCoordinator.Gear(state,Now);Check(keyboardAttempt.CanReleaseSoftwareLighting&&!keyboardAttempt.CanStaticRgb,"Exact keyboard flags permit ownership attempt despite rejected RGB GET");
  var releasedKeyboardState=MouseState(false);releasedKeyboardState["kind"]="keyboard";releasedKeyboardState["pid"]=7588;((Dictionary<string,object>)releasedKeyboardState["snapshot"]).Remove("lighting");var releasedKeyboard=AuraSyncCoordinator.Gear(releasedKeyboardState,Now);ownershipReads=0;sends=0;
  ownership=await new AuraSyncCoordinator().TakeSoftwareLightingAsync(keyboardAttempt,target=>Task.FromResult(++ownershipReads==1||ownershipReads==4?keyboardAttempt:releasedKeyboard),command=>{sends++;Check(command.Setting=="lightingSoftwareMode","Rejected keyboard recipe never guessed or written");return Task.FromResult(Confirm());},()=>{});
  Check(!ownership.OwnershipConfirmed&&ownership.RestorationConfirmed&&sends==2,"Keyboard recipe still rejected restores only original SW flag");
