  var returned=await new AuraSyncCoordinator().ReturnSoftwareLightingAsync(ownedReceipt,target=>Task.FromResult(++ownershipReads==1?released:streaming),command=>{sends++;Check(command.Setting=="lightingSoftwareMode"&&(bool)command.Request["value"],"Return only original SW=true, no color/profile action");return Task.FromResult(Confirm());},()=>gates++);
  Check(returned.State=="returned"&&returned.RestorationConfirmed&&!returned.CanReturnOriginalFlag&&sends==1&&gates==1,"Manual return fresh identity, gate and getter confirmation");
  sends=0;returned=await new AuraSyncCoordinator().ReturnSoftwareLightingAsync(ownedReceipt,target=>Fresh(streaming),command=>{sends++;return Task.FromResult(Confirm());},()=>{});Check(returned.RestorationConfirmed&&sends==0,"Original SW flag already present requires no output");
  sends=0;returned=await new AuraSyncCoordinator().ReturnSoftwareLightingAsync(ownedReceipt,Fresh,command=>{sends++;return Task.FromResult(Confirm());},()=>{throw new InvalidOperationException("disabled");});Check(!returned.RestorationConfirmed&&sends==0&&!returned.WriteAttempted,"Return cannot bypass disabled session policy");
  sends=0;returned=await new AuraSyncCoordinator().ReturnSoftwareLightingAsync(ownedReceipt,target=>{throw new TimeoutException("offline");},command=>{sends++;return Task.FromResult(Confirm());},()=>{});Check(!returned.RestorationConfirmed&&sends==0,"Offline return not guessed or retried");
  var switched=MouseState(false);switched["deviceId"]="hid-other-synthetic";sends=0;returned=await new AuraSyncCoordinator().ReturnSoftwareLightingAsync(ownedReceipt,target=>Fresh(AuraSyncCoordinator.Gear(switched,Now)),command=>{sends++;return Task.FromResult(Confirm());},()=>{});Check(!returned.RestorationConfirmed&&sends==0,"Changed identity cannot receive original-flag write");
  Reject(()=>new AuraSyncCoordinator().ReturnSoftwareLightingAsync(new AuraOwnershipResult{Target=released},Fresh,command=>Task.FromResult(Confirm()),()=>{}).GetAwaiter().GetResult(),"No return for an unowned or restored preview draft");
  ownershipReads=0;sends=0;returned=await new AuraSyncCoordinator().ReturnSoftwareLightingAsync(ownedReceipt,target=>{if(++ownershipReads==1)return Fresh(released);throw new TimeoutException("lost after write");},command=>{sends++;return Task.FromResult(Confirm());},()=>{});Check(!returned.RestorationConfirmed&&returned.WriteAttempted&&sends==1,"Return ACK followed by offline remains unconfirmed, no retry");
 }
